    output [7:0] out
);

    assign out = (~sel & a) | (sel & b);

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  w,
    output z
);

reg [2:0] current_state;
reg [2:0] next_state;

// State register
always @(posedge clk) begin
    if (reset)
        current_state <= 3'b000;
    else
        current_state <= next_state;
end

// State transition logic
always @(current_state, w) begin
    case (current_state)
        3'b000: // A
            if (w) next_state = 3'b001;
            else next_state = 3'b000;
        3'b001: // B
            if (w) next_state = 3'b010;
            else next_state = 3'b011;
        3'b010: // C
            if (w) next_state = 3'b100;
            else next_state = 3'b011;
        3'b011: // D
            if (w) next_state = 3'b110;
            else next_state = 3'b000;
        3'b100: // E
            if (w) next_state = 3'b100;
            else next_state = 3'b011;
        3'b110: // F
            if (w) next_state = 3'b010;
            else next_state = 3'b011;
    endcase
end

// Output logic
assign z = (current_state == 3'b100) ? 1'b1 : 1'b0;

endmodule

module TopModule (
    input  clk,
    input  in,
    input  reset,
    output reg [7:0] out_byte,
    output reg done
);

reg [1:0] state;
reg [7:0] data_reg;
reg [3:0] count_data;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= 2'b00;
        data_reg <= 8'b0;
        count_data <= 4'd0;
        out_byte <= 8'b0;
        done <= 1'b0;
    end else begin
        case (state)
            2'b00: begin // IDLE
                if (in == 1'b0) begin
                    state <= 2'b01;
                    data_reg <= 8'b0;
                    count_data <= 4'd0;
                end else begin
                    state <= 2'b00;
                end
                done <= 1'b0;
                out_byte <= 8'b0;
            end
            2'b01: begin // RECEIVE_DATA
                data_reg <= data_reg << 1 | in;
                count_data <= count_data + 1;
                if (count_data == 4'd8) begin
                    state <= 2'b10;
                end else begin
                    state <= 2'b01;
                end
                done <= 1'b0;
                out_byte <= 8'b0;
            end
            2'b10: begin // RECEIVE_STOP
                if (in == 1'b1) begin
                    done <= 1'b1;
                    out_byte <= data_reg;
                    state <= 2'b00;
                end else begin
                    state <= 2'b10;
                end
            end
        endcase
    end
end

endmodule
